//! Pure CONTRACT-057 v1.0.0 loader metadata schema builders.
//!
//! These functions reproduce the structure generated by the public TypeScript
//! `generateDomainPackLoaderSchema()` and `generateLoaderInventorySchema()`.
//! They only return schema data: admission, transport, execution, URL discovery,
//! and loader qualification are outside this module.

use crate::{
    domain_pack_schema::{generated_schema_graph_json, GeneratedSchemaGraph},
    error::EngineError,
    value::{Utf16, Value},
};

fn text(value: &str) -> Value {
    Value::String(Utf16::from(value))
}

fn object(fields: &[(&str, Value)]) -> Value {
    Value::Object(
        fields
            .iter()
            .map(|(key, value)| (Utf16::from(*key), value.clone()))
            .collect(),
    )
}

fn array(values: &[&str]) -> Value {
    Value::Array(values.iter().map(|value| text(value)).collect())
}

fn integer(value: usize) -> Value {
    Value::Number(value as f64)
}

fn nonempty_text() -> Value {
    object(&[("type", text("string")), ("minLength", integer(1))])
}

fn bounded_integer(minimum: usize, maximum: usize) -> Value {
    object(&[
        ("type", text("integer")),
        ("minimum", integer(minimum)),
        ("maximum", integer(maximum)),
    ])
}

/// Build the CONTRACT-057 domain-pack loader annotation schema, version 1.0.0.
///
/// The result is isolated and supports only the exact declaration profile in
/// CONTRACT-057. Unknown annotation properties remain structurally permitted.
pub fn generate_domain_pack_loader_schema() -> Value {
    let nonempty = nonempty_text();
    let path = object(&[
        ("type", text("string")),
        (
            "pattern",
            text("^(?!/)(?!.*(?:^|/)\\.\\.?/)[A-Za-z0-9_-]+(?:[./][A-Za-z0-9_-]+)*$"),
        ),
    ]);
    let checksum = object(&[
        ("type", text("string")),
        ("pattern", text("^[a-f0-9]{64}$")),
    ]);
    let artifact = object(&[
        ("type", text("object")),
        ("required", array(&["reference", "sha256"])),
        (
            "properties",
            object(&[("reference", path), ("sha256", checksum)]),
        ),
        ("additionalProperties", Value::Bool(true)),
    ]);
    object(&[
        (
            "$schema",
            text("https://json-schema.org/draft/2020-12/schema"),
        ),
        ("$id", text("urn:umf:domain-pack-loader:1.0.0")),
        ("type", text("object")),
        (
            "required",
            array(&[
                "version",
                "id",
                "implementation_version",
                "profile",
                "runtime",
                "entrypoint",
                "configuration_schema",
                "qualification",
                "artifacts",
            ]),
        ),
        (
            "properties",
            object(&[
                ("version", object(&[("const", text("1.0.0"))])),
                ("id", object(&[("const", text("umf.document-loader"))])),
                (
                    "implementation_version",
                    object(&[("const", text("1.0.0"))]),
                ),
                (
                    "profile",
                    object(&[(
                        "enum",
                        array(&["court-documents", "sec-filings", "documents"]),
                    )]),
                ),
                ("runtime", object(&[("const", text("bun"))])),
                ("entrypoint", object(&[("const", text("run.ts"))])),
                (
                    "configuration_schema",
                    object(&[("const", text("inventory.schema.json"))]),
                ),
                ("qualification", nonempty),
                (
                    "artifacts",
                    object(&[
                        ("type", text("array")),
                        ("minItems", integer(2)),
                        ("maxItems", integer(32)),
                        ("items", artifact),
                    ]),
                ),
            ]),
        ),
        ("additionalProperties", Value::Bool(true)),
    ])
}

/// Build the CONTRACT-057 finite inventory schema, version 1.0.0.
///
/// This establishes only structural bounds. It does not authorize or perform
/// network retrieval, URL policy checks, rights evaluation, or document loading.
pub fn generate_loader_inventory_schema() -> Value {
    let text_schema = object(&[
        ("type", text("string")),
        ("minLength", integer(1)),
        ("maxLength", integer(4096)),
    ]);
    let license = object(&[
        ("type", text("object")),
        ("required", array(&["redistribution"])),
        (
            "properties",
            object(&[(
                "redistribution",
                object(&[("enum", array(&["allowed", "restricted", "unknown"]))]),
            )]),
        ),
        ("additionalProperties", Value::Bool(true)),
    ]);
    let entry = object(&[
        ("type", text("object")),
        ("required", array(&["id", "url", "media_type", "license"])),
        (
            "properties",
            object(&[
                ("id", text_schema.clone()),
                ("url", text_schema.clone()),
                (
                    "media_type",
                    object(&[(
                        "enum",
                        array(&[
                            "application/pdf",
                            "application/json",
                            "text/html",
                            "text/plain",
                        ]),
                    )]),
                ),
                (
                    "expected_sha256",
                    object(&[
                        ("type", text("string")),
                        ("pattern", text("^[a-f0-9]{64}$")),
                    ]),
                ),
                ("license", license),
                ("metadata", object(&[("type", text("object"))])),
            ]),
        ),
        ("additionalProperties", Value::Bool(true)),
    ]);
    object(&[
        (
            "$schema",
            text("https://json-schema.org/draft/2020-12/schema"),
        ),
        ("$id", text("urn:umf:loader-inventory:1.0.0")),
        ("type", text("object")),
        (
            "required",
            array(&[
                "version",
                "id",
                "allowed_hosts",
                "request_interval_ms",
                "max_bytes",
                "max_total_bytes",
                "max_documents",
                "timeout_ms",
                "retries",
                "entries",
            ]),
        ),
        (
            "properties",
            object(&[
                ("version", object(&[("const", text("1.0.0"))])),
                ("id", text_schema.clone()),
                (
                    "allowed_hosts",
                    object(&[
                        ("type", text("array")),
                        ("minItems", integer(1)),
                        ("maxItems", integer(32)),
                        ("uniqueItems", Value::Bool(true)),
                        ("items", text_schema.clone()),
                    ]),
                ),
                ("request_interval_ms", bounded_integer(100, 60_000)),
                ("max_bytes", bounded_integer(1, 50 * 1024 * 1024)),
                ("max_total_bytes", bounded_integer(1, 500 * 1024 * 1024)),
                ("max_documents", bounded_integer(1, 1000)),
                ("timeout_ms", bounded_integer(1000, 60_000)),
                ("retries", bounded_integer(0, 3)),
                (
                    "entries",
                    object(&[
                        ("type", text("array")),
                        ("maxItems", integer(1000)),
                        ("items", entry),
                    ]),
                ),
            ]),
        ),
        ("additionalProperties", Value::Bool(true)),
    ])
}

/// Return the public loader schema and its TypeScript predecessor identity
/// metadata. This schema has no repeated object references.
pub fn generate_domain_pack_loader_schema_graph() -> GeneratedSchemaGraph {
    GeneratedSchemaGraph {
        schema: generate_domain_pack_loader_schema(),
        alias_groups: Vec::new(),
    }
}

/// Return the public inventory schema and its TypeScript predecessor identity
/// metadata. Its shared text schema occupies four JSON Pointer locations.
pub fn generate_loader_inventory_schema_graph() -> GeneratedSchemaGraph {
    GeneratedSchemaGraph {
        schema: generate_loader_inventory_schema(),
        alias_groups: vec![vec![
            "/properties/id".to_owned(),
            "/properties/allowed_hosts/items".to_owned(),
            "/properties/entries/items/properties/id".to_owned(),
            "/properties/entries/items/properties/url".to_owned(),
        ]],
    }
}

/// Return pretty JSON carrying the loader schema and its alias-group sidecar.
pub fn domain_pack_loader_schema_graph_json() -> Result<String, EngineError> {
    generated_schema_graph_json(generate_domain_pack_loader_schema_graph())
}

/// Return pretty JSON carrying the inventory schema and its alias-group sidecar.
pub fn loader_inventory_schema_graph_json() -> Result<String, EngineError> {
    generated_schema_graph_json(generate_loader_inventory_schema_graph())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        context::Context,
        serialization::{write_json_value, Format},
    };

    const LOADER_SCHEMA_V1: &str =
        include_str!("../../../spec/loader-companion/1.0.0/loader.schema.json");
    const INVENTORY_SCHEMA_V1: &str =
        include_str!("../../../spec/loader-companion/1.0.0/inventory.schema.json");

    fn pretty(value: &Value) -> String {
        write_json_value(value, Format::Json, &mut Context::ordinary())
            .expect("schema serializes")
            .to_utf8()
            .expect("schema is UTF-8")
    }

    fn canonical_with_id(canonical: &str, id: &str) -> String {
        let mut lines = canonical.lines();
        let first = lines.next().expect("schema is nonempty");
        let schema = lines.next().expect("schema has $schema");
        assert_eq!(
            schema,
            "  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\","
        );
        format!(
            "{first}\n{schema}\n  \"$id\": \"{id}\",\n{}\n",
            lines.collect::<Vec<_>>().join("\n")
        )
    }

    fn assert_canonical_schema(generated: Value, canonical: &str, id: &str) {
        let generated_pretty = pretty(&generated);
        let canonical_with_id = canonical_with_id(canonical, id);
        let expected: serde_json::Value =
            serde_json::from_str(&canonical_with_id).expect("canonical JSON schema");
        let generated_parsed: serde_json::Value =
            serde_json::from_str(&generated_pretty).expect("generated JSON schema");
        assert_eq!(
            generated_pretty.as_bytes(),
            canonical_with_id.as_bytes(),
            "pretty bytes"
        );
        assert_eq!(generated_parsed, expected, "full structural parity");
        assert!(generated_pretty.ends_with('\n'));
        assert!(!generated_pretty.ends_with("\r\n"));
    }

    fn pointer<'a>(value: &'a Value, path: &str) -> Option<&'a Value> {
        let mut current = value;
        for segment in path.strip_prefix('/')?.split('/') {
            let segment = segment.replace("~1", "/").replace("~0", "~");
            match current {
                Value::Object(members) => {
                    current = &members
                        .iter()
                        .find(|(key, _)| key.to_utf8().ok().as_deref() == Some(&segment))?
                        .1;
                }
                Value::Array(items) => current = items.get(segment.parse::<usize>().ok()?)?,
                _ => return None,
            }
        }
        Some(current)
    }

    #[test]
    fn loader_schema_matches_the_complete_v1_predecessor_resource() {
        assert_canonical_schema(
            generate_domain_pack_loader_schema(),
            LOADER_SCHEMA_V1,
            "urn:umf:domain-pack-loader:1.0.0",
        );
        let loader_canonical =
            canonical_with_id(LOADER_SCHEMA_V1, "urn:umf:domain-pack-loader:1.0.0");
        let schema: serde_json::Value = serde_json::from_str(&loader_canonical).unwrap();
        assert_eq!(schema["$id"], "urn:umf:domain-pack-loader:1.0.0");
        assert_eq!(schema["properties"]["version"]["const"], "1.0.0");
        assert_eq!(schema["properties"]["artifacts"]["minItems"], 2);
        assert_eq!(schema["properties"]["artifacts"]["maxItems"], 32);
    }

    #[test]
    fn inventory_schema_matches_complete_v1_predecessor_and_pinned_bounds() {
        assert_canonical_schema(
            generate_loader_inventory_schema(),
            INVENTORY_SCHEMA_V1,
            "urn:umf:loader-inventory:1.0.0",
        );
        let inventory_canonical =
            canonical_with_id(INVENTORY_SCHEMA_V1, "urn:umf:loader-inventory:1.0.0");
        let schema: serde_json::Value = serde_json::from_str(&inventory_canonical).unwrap();
        assert_eq!(schema["$id"], "urn:umf:loader-inventory:1.0.0");
        assert_eq!(schema["properties"]["version"]["const"], "1.0.0");
        let props = &schema["properties"];
        assert_eq!(props["allowed_hosts"]["maxItems"], 32);
        assert_eq!(props["request_interval_ms"]["minimum"], 100);
        assert_eq!(props["request_interval_ms"]["maximum"], 60000);
        assert_eq!(props["max_bytes"]["maximum"], 50 * 1024 * 1024);
        assert_eq!(props["max_total_bytes"]["maximum"], 500 * 1024 * 1024);
        assert_eq!(props["max_documents"]["maximum"], 1000);
        assert_eq!(props["timeout_ms"]["minimum"], 1000);
        assert_eq!(props["timeout_ms"]["maximum"], 60000);
        assert_eq!(props["retries"]["maximum"], 3);
        assert_eq!(props["entries"]["maxItems"], 1000);
        assert_eq!(
            props["entries"]["items"]["properties"]["id"]["maxLength"],
            4096
        );
    }

    #[test]
    fn loader_schema_graph_has_no_predecessor_object_aliases() {
        let graph = generate_domain_pack_loader_schema_graph();
        assert!(graph.alias_groups.is_empty());
        assert_eq!(graph.schema, generate_domain_pack_loader_schema());
        let wire: serde_json::Value =
            serde_json::from_str(&domain_pack_loader_schema_graph_json().unwrap()).unwrap();
        assert_eq!(wire["schema"]["$id"], "urn:umf:domain-pack-loader:1.0.0");
        assert_eq!(wire["aliasGroups"], serde_json::json!([]));
    }

    #[test]
    fn inventory_schema_graph_records_the_exhaustive_shared_text_alias_class() {
        let graph = generate_loader_inventory_schema_graph();
        let expected = vec![vec![
            "/properties/id".to_owned(),
            "/properties/allowed_hosts/items".to_owned(),
            "/properties/entries/items/properties/id".to_owned(),
            "/properties/entries/items/properties/url".to_owned(),
        ]];
        assert_eq!(graph.alias_groups, expected);
        let first = pointer(&graph.schema, &graph.alias_groups[0][0]).unwrap();
        for path in &graph.alias_groups[0] {
            assert_eq!(
                pointer(&graph.schema, path),
                Some(first),
                "alias path {path}"
            );
        }
        let wire: serde_json::Value =
            serde_json::from_str(&loader_inventory_schema_graph_json().unwrap()).unwrap();
        assert_eq!(wire["schema"]["$id"], "urn:umf:loader-inventory:1.0.0");
        assert_eq!(wire["aliasGroups"], serde_json::json!(expected));
    }
}
